def inputs(self, i: int, narrative: bool = True) -> ForecastInputs:
    context = self.context[i]
    if self.config.track.startswith("FD"):
        context = narrate(self.raw[i], self.config) if narrative else [""] * self.config.window
    return ForecastInputs(self.raw[i].tolist(), self.timestamps[i], context,
        self.feature_names, (f"Predict remaining useful life at the final observed engine cycle, in cycles. Labels are capped at {self.config.max_rul:g} cycles (a healthy engine has RUL {self.config.max_rul:g}), so the answer lies between 0 and {self.config.max_rul:g}; once degradation begins, RUL falls by one per operating cycle. Isolated sensor-deviation flags are common in healthy engines because of measurement noise and are not evidence of imminent failure; an RUL below about 30 cycles requires many sensors to show large, sustained deviations over many consecutive cycles."
        if self.target_index is None else f"Predict future {self.feature_names[self.target_index]} values in original units."),
        self.config.horizon, self.target_index)
